#!/usr/bin/env python3
"""统计 CSV 文件每一列的非空值数量。"""

import argparse
import csv
import sys
from collections import Counter


def count_non_empty(path: str) -> tuple[list[str], Counter]:
    with open(path, newline="", encoding="utf-8-sig") as f:
        reader = csv.reader(f)
        try:
            header = next(reader)
        except StopIteration:
            return [], Counter()

        counts = Counter()
        for row in reader:
            for idx in range(len(header)):
                value = row[idx].strip() if idx < len(row) else ""
                if value:
                    counts[idx] += 1

        names = [name.strip() or f"column_{i + 1}" for i, name in enumerate(header)]
        return names, counts


def main() -> int:
    parser = argparse.ArgumentParser(description="统计 CSV 每一列的非空值数量")
    parser.add_argument("csv_file", help="CSV 文件路径")
    args = parser.parse_args()

    try:
        names, counts = count_non_empty(args.csv_file)
    except FileNotFoundError:
        print(f"文件不存在: {args.csv_file}", file=sys.stderr)
        return 1
    except UnicodeDecodeError:
        print(f"编码错误，请使用 UTF-8 编码的文件: {args.csv_file}", file=sys.stderr)
        return 1

    if not names:
        print("文件为空，没有可统计的列。")
        return 0

    width = max(len(n) for n in names)
    for i, name in enumerate(names):
        print(f"{name.ljust(width)}: {counts[i]}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
